macro_rules! deps {
    () => {
        Anchored!();
        DFA!();
        Cache!();
        Match!();
        Input!();
        CachePool!();
        PikeVM!();
        RegexI!();
    };
}

macro_rules! Regex {
    () => {
        deps!();
        # [doc = " A regex matcher that works by composing several other regex matchers"] # [doc = " automatically."] # [doc = ""] # [doc = " In effect, a meta regex papers over a lot of the quirks or performance"] # [doc = " problems in each of the regex engines in this crate. Its goal is to provide"] # [doc = " an infallible and simple API that \"just does the right thing\" in the common"] # [doc = " case."] # [doc = ""] # [doc = " A meta regex is the implementation of a `Regex` in the `regex` crate."] # [doc = " Indeed, the `regex` crate API is essentially just a light wrapper over"] # [doc = " this type. This includes the `regex` crate's `RegexSet` API!"] # [doc = ""] # [doc = " # Composition"] # [doc = ""] # [doc = " This is called a \"meta\" matcher precisely because it uses other regex"] # [doc = " matchers to provide a convenient high level regex API. Here are some"] # [doc = " examples of how other regex matchers are composed:"] # [doc = ""] # [doc = " * When calling [`Regex::captures`], instead of immediately"] # [doc = " running a slower but more capable regex engine like the"] # [doc = " [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM), the meta regex engine"] # [doc = " will usually first look for the bounds of a match with a higher throughput"] # [doc = " regex engine like a [lazy DFA](crate::hybrid). Only when a match is found"] # [doc = " is a slower engine like `PikeVM` used to find the matching span for each"] # [doc = " capture group."] # [doc = " * While higher throughout engines like the lazy DFA cannot handle"] # [doc = " Unicode word boundaries in general, they can still be used on pure ASCII"] # [doc = " haystacks by pretending that Unicode word boundaries are just plain ASCII"] # [doc = " word boundaries. However, if a haystack is not ASCII, the meta regex engine"] # [doc = " will automatically switch to a (possibly slower) regex engine that supports"] # [doc = " Unicode word boundaries in general."] # [doc = " * In some cases where a regex pattern is just a simple literal or a small"] # [doc = " set of literals, an actual regex engine won't be used at all. Instead,"] # [doc = " substring or multi-substring search algorithms will be employed."] # [doc = ""] # [doc = " There are many other forms of composition happening too, but the above"] # [doc = " should give a general idea. In particular, it may perhaps be surprising"] # [doc = " that *multiple* regex engines might get executed for a single search. That"] # [doc = " is, the decision of what regex engine to use is not _just_ based on the"] # [doc = " pattern, but also based on the dynamic execution of the search itself."] # [doc = ""] # [doc = " The primary reason for this composition is performance. The fundamental"] # [doc = " tension is that the faster engines tend to be less capable, and the more"] # [doc = " capable engines tend to be slower."] # [doc = ""] # [doc = " Note that the forms of composition that are allowed are determined by"] # [doc = " compile time crate features and configuration. For example, if the `hybrid`"] # [doc = " feature isn't enabled, or if [`Config::hybrid`] has been disabled, then the"] # [doc = " meta regex engine will never use a lazy DFA."] # [doc = ""] # [doc = " # Synchronization and cloning"] # [doc = ""] # [doc = " Most of the regex engines in this crate require some kind of mutable"] # [doc = " \"scratch\" space to read and write from while performing a search. Since"] # [doc = " a meta regex composes these regex engines, a meta regex also requires"] # [doc = " mutable scratch space. This scratch space is called a [`Cache`]."] # [doc = ""] # [doc = " Most regex engines _also_ usually have a read-only component, typically"] # [doc = " a [Thompson `NFA`](crate::nfa::thompson::NFA)."] # [doc = ""] # [doc = " In order to make the `Regex` API convenient, most of the routines hide"] # [doc = " the fact that a `Cache` is needed at all. To achieve this, a [memory"] # [doc = " pool](crate::util::pool::Pool) is used internally to retrieve `Cache`"] # [doc = " values in a thread safe way that also permits reuse. This in turn implies"] # [doc = " that every such search call requires some form of synchronization. Usually"] # [doc = " this synchronization is fast enough to not notice, but in some cases, it"] # [doc = " can be a bottleneck. This typically occurs when all of the following are"] # [doc = " true:"] # [doc = ""] # [doc = " * The same `Regex` is shared across multiple threads simultaneously,"] # [doc = " usually via a [`util::lazy::Lazy`](crate::util::lazy::Lazy) or something"] # [doc = " similar from the `once_cell` or `lazy_static` crates."] # [doc = " * The primary unit of work in each thread is a regex search."] # [doc = " * Searches are run on very short haystacks."] # [doc = ""] # [doc = " This particular case can lead to high contention on the pool used by a"] # [doc = " `Regex` internally, which can in turn increase latency to a noticeable"] # [doc = " effect. This cost can be mitigated in one of the following ways:"] # [doc = ""] # [doc = " * Use a distinct copy of a `Regex` in each thread, usually by cloning it."] # [doc = " Cloning a `Regex` _does not_ do a deep copy of its read-only component."] # [doc = " But it does lead to each `Regex` having its own memory pool, which in"] # [doc = " turn eliminates the problem of contention. In general, this technique should"] # [doc = " not result in any additional memory usage when compared to sharing the same"] # [doc = " `Regex` across multiple threads simultaneously."] # [doc = " * Use lower level APIs, like [`Regex::search_with`], which permit passing"] # [doc = " a `Cache` explicitly. In this case, it is up to you to determine how best"] # [doc = " to provide a `Cache`. For example, you might put a `Cache` in thread-local"] # [doc = " storage if your use case allows for it."] # [doc = ""] # [doc = " Overall, this is an issue that happens rarely in practice, but it can"] # [doc = " happen."] # [doc = ""] # [doc = " # Warning: spin-locks may be used in alloc-only mode"] # [doc = ""] # [doc = " When this crate is built without the `std` feature and the high level APIs"] # [doc = " on a `Regex` are used, then a spin-lock will be used to synchronize access"] # [doc = " to an internal pool of `Cache` values. This may be undesirable because"] # [doc = " a spin-lock is [effectively impossible to implement correctly in user"] # [doc = " space][spinlocks-are-bad]. That is, more concretely, the spin-lock could"] # [doc = " result in a deadlock."] # [doc = ""] # [doc = " [spinlocks-are-bad]: https://matklad.github.io/2020/01/02/spinlocks-considered-harmful.html"] # [doc = ""] # [doc = " If one wants to avoid the use of spin-locks when the `std` feature is"] # [doc = " disabled, then you must use APIs that accept a `Cache` value explicitly."] # [doc = " For example, [`Regex::search_with`]."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::meta::Regex;"] # [doc = ""] # [doc = " let re = Regex::new(r\"^[0-9]{4}-[0-9]{2}-[0-9]{2}$\")?;"] # [doc = " assert!(re.is_match(\"2010-03-14\"));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: anchored search"] # [doc = ""] # [doc = " This example shows how to use [`Input::anchored`] to run an anchored"] # [doc = " search, even when the regex pattern itself isn't anchored. An anchored"] # [doc = " search guarantees that if a match is found, then the start offset of the"] # [doc = " match corresponds to the offset at which the search was started."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{meta::Regex, Anchored, Input, Match};"] # [doc = ""] # [doc = " let re = Regex::new(r\"\\bfoo\\b\")?;"] # [doc = " let input = Input::new(\"xx foo xx\").range(3..).anchored(Anchored::Yes);"] # [doc = " // The offsets are in terms of the original haystack."] # [doc = " assert_eq!(Some(Match::must(0, 3..6)), re.find(input));"] # [doc = ""] # [doc = " // Notice that no match occurs here, because \\b still takes the"] # [doc = " // surrounding context into account, even if it means looking back"] # [doc = " // before the start of your search."] # [doc = " let hay = \"xxfoo xx\";"] # [doc = " let input = Input::new(hay).range(2..).anchored(Anchored::Yes);"] # [doc = " assert_eq!(None, re.find(input));"] # [doc = " // Indeed, you cannot achieve the above by simply slicing the"] # [doc = " // haystack itself, since the regex engine can't see the"] # [doc = " // surrounding context. This is why 'Input' permits setting"] # [doc = " // the bounds of a search!"] # [doc = " let input = Input::new(&hay[2..]).anchored(Anchored::Yes);"] # [doc = " // WRONG!"] # [doc = " assert_eq!(Some(Match::must(0, 0..3)), re.find(input));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: earliest search"] # [doc = ""] # [doc = " This example shows how to use [`Input::earliest`] to run a search that"] # [doc = " might stop before finding the typical leftmost match."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{meta::Regex, Anchored, Input, Match};"] # [doc = ""] # [doc = " let re = Regex::new(r\"[a-z]{3}|b\")?;"] # [doc = " let input = Input::new(\"abc\").earliest(true);"] # [doc = " assert_eq!(Some(Match::must(0, 1..2)), re.find(input));"] # [doc = ""] # [doc = " // Note that \"earliest\" isn't really a match semantic unto itself."] # [doc = " // Instead, it is merely an instruction to whatever regex engine"] # [doc = " // gets used internally to quit as soon as it can. For example,"] # [doc = " // this regex uses a different search technique, and winds up"] # [doc = " // producing a different (but valid) match!"] # [doc = " let re = Regex::new(r\"abc|b\")?;"] # [doc = " let input = Input::new(\"abc\").earliest(true);"] # [doc = " assert_eq!(Some(Match::must(0, 0..3)), re.find(input));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: change the line terminator"] # [doc = ""] # [doc = " This example shows how to enable multi-line mode by default and change"] # [doc = " the line terminator to the NUL byte:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{meta::Regex, util::syntax, Match};"] # [doc = ""] # [doc = " let re = Regex::builder()"] # [doc = "     .syntax(syntax::Config::new().multi_line(true))"] # [doc = "     .configure(Regex::config().line_terminator(b'\\x00'))"] # [doc = "     .build(r\"^foo$\")?;"] # [doc = " let hay = \"\\x00foo\\x00\";"] # [doc = " assert_eq!(Some(Match::must(0, 1..4)), re.find(hay));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Debug)] pub struct Regex { # [doc = " The actual regex implementation."] imp : Arc < RegexI > , # [doc = " A thread safe pool of caches."] # [doc = ""] # [doc = " For the higher level search APIs, a `Cache` is automatically plucked"] # [doc = " from this pool before running a search. The lower level `with` methods"] # [doc = " permit the caller to provide their own cache, thereby bypassing"] # [doc = " accesses to this pool."] # [doc = ""] # [doc = " Note that we put this outside the `Arc` so that cloning a `Regex`"] # [doc = " results in creating a fresh `CachePool`. This in turn permits callers"] # [doc = " to clone regexes into separate threads where each such regex gets"] # [doc = " the pool's \"thread owner\" optimization. Otherwise, if one shares the"] # [doc = " `Regex` directly, then the pool will go through a slower mutex path for"] # [doc = " all threads except for the \"owner.\""] pool : CachePool , }
    };
}

Regex!();